    public static int lengthOfLIS(int[] nums) {
        if (nums.length == 0) return 0;

        int maxLen = 1;

        int ctr = 0;
        while (ctr < nums.length) {
            int tempCtr = ctr;

            while (true) {
                if (tempCtr < nums.length - 1) {
                    if (nums[tempCtr + 1] < nums[tempCtr]) {
                        break;
                    } else {
                        tempCtr++;
                    }
                } else {
                    break;
                }
            }

            if (tempCtr - ctr + 1 > maxLen) {
                maxLen = tempCtr - ctr + 1;
                startingIndex = ctr;
            }

            ctr = tempCtr + 1;
        }

        return maxLen;
    }
